<?php

declare(strict_types=1);

// Help texts of the System status tab (lib/help/system_status.php). Split out of
// help.php, which had grown past the 400-line module budget: the tab already had
// its own renderer, so its strings get their own module rather than an arbitrary
// cut through one catalog. Keys are reached as __t('help_system_status.<key>').

return [
    'system_status_roles_heading' => 'Einstellungen, Zugangsdaten und Systemstatus',
    'system_status_roles_p1' => 'Einstellungen steuern globales Verhalten, Zugangsdaten speichern verschlüsselte Ansible- und ESXi-Konten, und der Systemstatus zeigt beobachtete Ergebnisse sowie berechtigte Diagnose- und Reparaturaktionen.',
    'system_status_single_site' => 'VirtuSphere bindet genau eine MECM-Site an. Mehrere IP-Freigaben erlauben mehreren Netzwerkadressen den Zugriff auf dieselbe Machine-API; sie bilden kein Multi-MECM.',
    'system_status_signals_heading' => 'Ergebnisberichte und Site-Zustand richtig lesen',
    'system_status_signal_heartbeat' => 'Ein aktueller Ergebnisbericht zeigt: Genau diese geplante Aufgabe ist auf dem MECM-Server gelaufen und hat ihr Ergebnis an das Portal gemeldet. Er sagt nichts über die anderen Aufgaben aus, jede meldet sich einzeln.',
    'system_status_signal_combination' => 'Die Integration (Datenfluss) und der MECM-Site-Zustand sind getrennt: Der Datenfluss kann grün laufen, während MECM selbst eine Warnung meldet, und ein ausgefallener Sync bedeutet nicht, dass MECM kritisch ist. Beide Badges deshalb einzeln lesen.',
    'directory_heading' => 'Active Directory',
    'directory_p1' => 'Die Karte fasst den Betriebszustand der LDAPS-Anmeldung zusammen: ob Active Directory aktiv ist, wie viele der eingetragenen Domänencontroller gerade einsatzbereit sind, und pro Controller Priorität, letzten Test, letzten Erfolg und Zertifikatsablauf. Sichtbar nur mit der Berechtigung „Benutzer verwalten"; Domänencontroller-Adressen sind interne Infrastruktur.',
    'directory_p2' => 'Fällt die Karte auf Gestört, prüft „Benutzer → Active Directory" zuerst das Suchkonto und den zuletzt gescheiterten Controller; das gefilterte Sicherheitsprotokoll zeigt die typisierte Ursache. Solange kein Controller einsatzbereit ist, bleibt die lokale Notfallanmeldung nutzbar.',
    'logs_heading' => 'Protokolle & Fehlersuche',
    'logs_p1' => 'Es gibt zwei Arten von Protokollen. Das Bereitstellungsprotokoll (Link „Protokoll" bei jedem Auftrag unter „Bereitstellung") zeigt die Ausgabe des laufenden Ansible-Auftrags in Echtzeit; hier schaut man hin, wenn eine Bereitstellung fehlschlägt. Das Audit-Protokoll unter „Protokolle" (nur Administratoren) hält dagegen fest, wer wann was im System geändert hat.',
    'logs_p2' => 'Das Audit-Protokoll ist in vier Bereiche unterteilt (Reiter oben), damit nicht alles in einer Tabelle landet: „Sicherheit" (Anmeldung & Zugriff, Benutzer, Zugangsdaten), „Ressourcen" (Missionen, VMs, VLANs, Betriebssysteme), „Deployment" (Bereitstellung, MECM-Integration) und „System & Integrationen" (System, Einstellungen, Legacy-API). Innerhalb eines Bereichs lässt sich weiter volltextsuchen sowie nach IP und einzelner Kategorie filtern. Die Kategorie „MECM-Integration" enthält bewusst nur wichtige Ereignisse: Ausfall und Wiederkehr einer überwachten Quelle, automatisch umgehängte Paketzuweisungen und abgelehnte Sync-Läufe. Einzelne Heartbeats werden nicht protokolliert, sonst wäre das Log binnen Stunden unlesbar.',
    'logs_p2b' => 'Der Bereich „Sicherheit" hält fest, wer Zugang zum System hat und hatte: erfolgreiche und fehlgeschlagene Anmeldungen, automatische Konto- und IP-Sperren, Abmeldungen, abgelaufene Sitzungen, Passwortwechsel sowie abgewiesene Anfragen (fehlende Berechtigung oder ungültiges CSRF-Token). Änderungs-Einträge nennen die geänderten Felder mit altem und neuem Wert; Geheimnisse und Notizen erscheinen nur als „geändert". Auch Datenabflüsse werden vermerkt: der JSON-Export einer Mission und die CSV-Listen-Exporte. Bereitstellungsaufträge protokollieren neben dem Einreihen auch ihr Ergebnis (erfolgreich oder fehlgeschlagen samt Grund).',
    'logs_p3' => 'Aufgeräumt wird automatisch durch den Wartungsdienst: Sicherheits-Protokolle (Anmeldung, Benutzer, Zugangsdaten) werden :security_days Tage aufbewahrt, alle übrigen Portal-Protokolleinträge :other_days Tage, der Anmeldeversuchs-Zähler :attempt_days Tage, Client-Phasen-Meldungen :client_days Tage, zurückgezogene Pakete ohne VM-Verknüpfung :package_days Tage. Niemand muss Protokolle von Hand löschen.',
    'logs_p4' => 'Auch die Ausgabe der Bereitstellungsaufträge wird aufgeräumt, aber erst :log_days Tage nachdem der Auftrag beendet ist. Ein laufender Auftrag verliert nie Zeilen. Missionsaufträge bleiben mit Status und Fehlermeldung in der Liste; öffnet man ihr Protokoll später, steht dort ein Hinweis statt einer leeren Tabelle. Missionslose ESXi-Inventaraufträge werden nach :system_days Tagen ganz entfernt. Bis dahin verlinkt ihre Karte im Systemstatus den letzten beendeten Auftrag direkt; danach zeigt sie bei einem alten Fehler einen Aufbewahrungshinweis statt eines toten Links.',
    'firstaid_heading' => 'Erste Schritte bei Fehlern',
    'firstaid_p1' => 'Egal was klemmt, die Reihenfolge ist immer dieselbe. So findet man in wenigen Minuten heraus, welche Komponente betroffen ist:',
    'firstaid_step1' => 'Systemstatus öffnen: Steht eine Quelle auf „Verzögert" oder „Ausgefallen"? Wenn ja, steht die passende Handlungsanweisung direkt daneben; die typischen Diagnosen weiter unten auf dieser Seite helfen zusätzlich.',
    'firstaid_step2' => 'Ist eine Bereitstellung fehlgeschlagen: unter „Bereitstellung" beim betroffenen Auftrag auf „Protokoll" klicken. Dort steht die komplette Ansible-Ausgabe mit der eigentlichen Fehlermeldung.',
    'firstaid_step3' => 'Hängt eine VM in der Windows-Installation (Stufe 4/5 oder 5/5): auf der Seite „VM bearbeiten" den Abschnitt „Client-Phasen" öffnen. Er zeigt, welcher Schritt zuletzt lief und ob einer fehlgeschlagen ist.',
    'firstaid_step4' => 'Reicht das nicht: Das Betriebshandbuch liegt im Projektordner auf dem Server (nicht im Portal erreichbar): docs/operations/mecm-integration.md. Es beschreibt die Log-Dateien auf dem MECM-Server und den Clients sowie die häufigsten Fälle Schritt für Schritt.',
    'system_status_heading' => 'Der Systemstatus: Gesundheitscheck auf einen Blick',
    'system_status_p1' => 'VirtuSphere funktioniert nur im Zusammenspiel mit Skripten, die auf dem MECM-Server laufen. Der Systemstatus ist die erste Anlaufstelle, wenn irgendetwas nicht ankommt: Er trennt MECM-Synchronisation, MECM-Site-Zustand, Ansible-Test, ESXi-Inventar und interne Dienste. Zu einem problematischen Zustand steht direkt eine Handlungsempfehlung.',
    'system_status_p2' => 'Die Seite ist bewusst für alle angemeldeten Benutzer sichtbar, nicht nur für Administratoren. Die erste Diagnose braucht also keine Admin-Rechte: Jeder kann nachsehen, ob eine Quelle auf „Ausgefallen" steht, bevor er ein Problem meldet.',
    'system_status_p3' => 'Die Seite ist eine Momentaufnahme des Ladezeitpunkts und aktualisiert sich nicht von selbst. „Stand der Anzeige" nennt diesen Zeitpunkt, „Status aktualisieren" holt einen neuen. Ein offenes Fenster wird also nicht grün, wenn das Problem behoben ist.',
    'system_status_sources_heading' => 'Was wird überwacht?',
    'system_status_source_1' => 'MECM Device-Sync. Geplante Aufgabe „VirtuSphere MECM Devices Sync", Skript mecm_new-device-sync.ps1. Sie fragt das Portal nach VMs, deren MAC-Adresse bekannt ist, legt sie als Geräte in MECM an und ordnet sie der Collection ihrer Mission zu. Läuft die Aufgabe nicht, bleibt jede neue VM auf Stufe 3/5 stehen: die MAC ist gemeldet, aber MECM lernt sie nie kennen.',
    'system_status_source_2' => 'MECM Paket-Sync. Geplante Aufgabe „VirtuSphere MECM Packages Sync", Skript mecm_Packages-TaskSeq-sync.ps1. Sie liest den Anwendungskatalog und die Task Sequences aus MECM aus und meldet sie an das Portal. Daraus entstehen die Seiten „Pakete" und „Betriebssysteme". Läuft die Aufgabe nicht, veraltet die Auswahl still: neue Pakete fehlen, zurückgezogene bleiben stehen.',
    'system_status_source_3' => 'MECM Paket-Import (Autoimporter). Geplante Aufgabe „VirtuSphere MECM Package Import", Skript mecm_autoimporter.ps1. Sie sieht im Paketordner auf dem MECM-Server nach und baut aus jedem neuen Unterordner mit config.json automatisch eine MECM-Anwendung samt Collection und Deployment. Läuft die Aufgabe nicht, bleiben abgelegte Pakete einfach liegen; sie erscheinen weder in MECM noch im Portal.',
    'system_status_source_4' => 'MECM Site-Health: der offizielle, von MECM gemeldete Site-Zustand (grün, gelb, rot). Ein eigener SYSTEM-Task auf dem MECM-Server fragt SMS_SummarizerSiteStatus ab und meldet den Zustand an das Portal.',
    'system_status_source_5' => 'Wartungsdienst (Portal). Keine geplante Aufgabe auf dem MECM-Server, sondern ein eigener Container auf dem Portal-Server, der dauerhaft mitläuft. Er erledigt die Aufräumarbeiten und die ESXi-Inventarplanung und meldet sich dabei selbst; sein Takt steht in der Zeile unter „Intervall". Steht er, bleiben diese Aufräum- und Planungsarbeiten liegen, die MECM-Aufgaben laufen davon unberührt weiter.',
    'system_status_status_heading' => 'Die Statusanzeige lesen',
    'system_status_status_p1' => 'Die MECM-Quellen sind PowerShell-Skripte, die auf dem MECM-Server in der Windows-Aufgabenplanung als geplante Aufgaben laufen. Nach jedem Durchlauf schicken sie eine kurze Meldung an das Portal; in der Fachsprache heißt so eine Meldung „Heartbeat". Das Portal fragt also nichts ab, es wartet nur. Kommt länger keine Meldung als der erwartete Takt, wechselt der Status. Jeder Zustand wird mit Text und Farbe angezeigt:',
    'system_status_status_p2' => 'Jede Zeile zeigt dieselben Felder in derselben Reihenfolge, auch wenn eine Quelle eines davon nie gemeldet hat. Ein Strich statt eines Werts bedeutet deshalb genau eines: zu diesem Feld ist nichts gespeichert. Er sagt nicht, dass das Ereignis nie eingetreten ist; eine Aufgabe, die noch nie fehlgeschlagen ist, und eine, deren Fehlerzeitpunkt nie ankam, sehen hier gleich aus. Eine Zeile aus einem alten Skript hat keinen Erfolgszeitpunkt, sondern nur ihre letzte Meldung; sie steht an derselben Stelle unter einem anderen Namen.',
    // Der Aufklappblock unter den Zählern. Vorher sendeten Device-Sync und
    // Autoimporter dort nichts, also nannte „Datenwarnungen: 3" keine einzige VM.
    'system_status_status_p3' => 'Zählt eine Zeile Datenwarnungen oder Fehler, steht unter „Technische Details" eine Ursachenzeile: je Fall ein kurzer Code, dahinter „target=" mit dem VM- oder Ordnernamen und, wenn es um eine Zuweisung geht, „collection=" mit der Collection. Also etwa „collection_missing target=WEB01 collection=Firefox-115.0". Damit findet man die betroffene VM ohne Suche im Log des MECM-Servers. Die Liste ist gedeckelt und sagt am Ende, wie viele Fälle nicht mehr dastehen. Die Zähler selbst beziehen sich immer nur auf den letzten Lauf: ein sauberer Lauf setzt sie zurück, deshalb gehört die Ursachenzeile gelesen, solange sie da ist.',
    'system_status_work_heading' => 'Mit den Status-Hinweisen arbeiten',
    'system_status_work_0' => 'Hat sich noch nie eine Synchronisationsaufgabe und kein Site-Health-Reporter gemeldet, ist MECM schlicht noch nicht angebunden. Dann stehen keine Hinweistexte an den Zeilen, denn dort ist nichts zu reparieren, was es noch nicht gibt; stattdessen nennt der Abschnitt einmal den nächsten Schritt.',
    'system_status_work_1' => 'Bei „Verzögert" oder „Ausgefallen" zuerst den Hinweistext direkt neben der Zeile lesen. Er nennt in Klartext die wahrscheinlichste Ursache und den nächsten Schritt; niemand muss die Bedeutung der Quellen auswendig kennen.',
    'system_status_work_2' => 'Den Schritt ausführen oder gezielt weitergeben: Manche Maßnahmen (geplante Aufgaben auf dem MECM-Server starten, Einstellungen ändern) brauchen Admin- oder Serverzugriff. Dann der zuständigen Person die betroffene Zeile samt Hinweistext melden; das erspart ihr die halbe Diagnose.',
    'system_status_work_3' => 'Nach der Behebung kurz warten: Jede Quelle meldet sich in ihrem festen Takt (Angabe „Intervall" in der Zeile). Die Zeile springt erst mit dem nächsten Heartbeat wieder auf „OK", nicht sofort nach dem Eingriff. Mit dem Wechsel auf „OK" verschwindet auch der Hinweistext, denn er ist eine Reparaturanweisung und keine Beschreibung.',
    'system_status_work_4' => 'Bleibt die Zeile trotzdem auf „Ausgefallen": mit den typischen Diagnosen weiter unten fortfahren und danach das Betriebshandbuch im Projektordner auf dem Server (nicht im Portal erreichbar) heranziehen: docs/operations/mecm-integration.md.',
    'system_status_fix_heading' => 'Typische Diagnosen',
    'system_status_fix_1' => 'Sync-Quellen auf „Ausgefallen", aber „MECM-Site" auf „OK" (grün): MECM selbst läuft, nur die geplanten Aufgaben melden sich nicht. Auf dem MECM-Server die Aufgabenplanung öffnen und die Tasks „VirtuSphere MECM Devices Sync", „VirtuSphere MECM Packages Sync" bzw. „VirtuSphere MECM Package Import" starten.',
    'system_status_fix_2' => 'MECM-Site auf „Ausgefallen" (rot): MECM selbst meldet den Site-Zustand kritisch. Details in der MECM-Konsole unter Monitoring, System Status prüfen. Ein grauer Providerfehler bedeutet dagegen nur, dass der Site-Health-Reporter den SMS-Provider nicht abfragen konnte, nicht dass MECM kritisch ist.',
    'system_status_fix_3' => '„Wartungsdienst" auf „Ausgefallen": Der interne Dienst des Portals steht. Auf dem Portal-Server (Ubuntu) im Projektverzeichnis „docker compose ps" prüfen und mit „docker compose up -d maintenance-worker" neu starten.',
    'system_status_fix_4' => 'Für tiefergehende Fälle (Logdateien auf dem MECM-Server, Sonderfälle der Skripte) gibt es das Betriebshandbuch im Projektordner auf dem Server (nicht im Portal erreichbar): docs/operations/mecm-integration.md.',
    'mecmfolders_heading' => 'Ordnerstruktur in der MECM-Konsole: was liegt wo?',
    'mecmfolders_p1' => 'Alle von VirtuSphere erzeugten Objekte liegen in drei fest benannten Ordnern der MECM-Konsole. So bleiben sie sauber von manuell gepflegten MECM-Objekten getrennt, und neues Personal findet sich sofort zurecht:',
    'mecmfolders_item1' => 'VirtuSphere_OS (unter Assets and Compliance → Device Collections): je Task-Sequenz eine gleichnamige Collection. Über sie erhalten VMs ihr Betriebssystem; angelegt vom Device-Sync.',
    'mecmfolders_item2' => 'VirtuSphere_Missions (ebenfalls unter Device Collections): je Mission eine Collection mit exakt dem Missionsnamen aus dem Portal; angelegt vom Device-Sync.',
    'mecmfolders_item3' => 'VirtuSphere_Applications: gibt es zweimal, einmal unter Device Collections (je Paket eine Collection „Name-Version") und einmal unter Software Library → Applications (die Anwendungen selbst); befüllt vom Autoimporter. Wichtig: Der Paket-Sync liest genau den Collections-Ordner als Katalogquelle. Nur Collections in diesem Ordner erscheinen im Portal als Pakete.',
    'mecmfolders_p2' => 'Alle drei Ordner legen die Skripte bei Bedarf selbst an, niemand muss sie von Hand erstellen (Voraussetzung: MECM-Konsole ab Version 2111; auf älteren Ständen die Ordner einmalig manuell anlegen). Die Geräte selbst landen ohne eigenen Ordner in „All Systems" und werden den Collections nur zugeordnet.',
    'mecmfolders_p3' => 'Für den Alltag heißt das: Ein Paket, dessen Collection außerhalb von VirtuSphere_Applications liegt, taucht nicht im Portal auf; nach dem Verschieben in den Ordner schon. Und die Ordner oder ihre Inhalte bitte nicht umbenennen, denn die Namen sind die Verbindung zwischen Portal und MECM.',
    'clientphases_heading' => 'Client-Phasen: die Windows-Installation im Blick',
    'clientphases_p1' => 'Ab Stufe 4/5 arbeitet nicht mehr das Portal, sondern die VM selbst: Sie bootet per PXE, installiert Windows, und kleine Skripte auf dem frisch installierten System melden ihren Fortschritt zurück. Auf der Seite „VM bearbeiten" zeigt der Abschnitt „Client-Phasen" vier Schritte, die immer in dieser Reihenfolge laufen:',
    'clientphases_step1' => 'getinfo: der Client holt seine Geräteinformationen (u. a. Netzwerkkarten) per MAC vom Portal und legt sie lokal in der Registry ab; die folgenden Phasen (hostname, staticip) lesen ihre Sollwerte von dort. Deshalb muss getinfo immer zuerst laufen.',
    'clientphases_step2' => 'hostname: der Computer wird auf den im Portal hinterlegten Hostnamen umbenannt und startet danach neu.',
    'clientphases_step3' => 'staticip: das Netzwerk wird auf die Zielkonfiguration umgestellt; dabei wechselt die VM häufig das VLAN und ist kurz nicht erreichbar.',
    'clientphases_step4' => 'disks: zusätzliche Festplatten werden online geschaltet (optional; VMs ohne Zusatzplatten überspringen den Schritt).',
    'clientphases_p2' => 'Jede Phase meldet „gestartet", „abgeschlossen" oder „fehlgeschlagen". Der Status „Ausgeführt, Bestätigung ausstehend" erscheint, wenn der Start gemeldet wurde, die Abschlussmeldung aber :minutes Minuten ausbleibt. Das ist meist harmlos: Nach der Umbenennung startet die VM neu, nach der Netzwerkumstellung hängt sie in einem anderen VLAN; in beiden Fällen kann die Abschlussmeldung das Portal schlicht nicht mehr erreichen.',
    'clientphases_p3' => 'Nur „Fehlgeschlagen" mit Detailtext ist ein echter Fehler. Dann hilft das Skript-Log direkt auf der betroffenen VM unter C:\\Program Files\\VirtuSphere\\Logs weiter.',
    'esxi_inv_heading' => 'ESXi-Inventar',
    'esxi_inv_p1' => 'Das Portal liest read-only in regelmäßigen Abständen aus den registrierten ESXi-Zugangsdaten: Datacenter, Datastores, Portgruppen und Host-Kapazität. Die Werte sind Snapshots vom letzten Abruf, kein Live-Monitoring. Der Abruf-Rhythmus wird in den Einstellungen gesetzt (Standard :hours Stunden); ein manueller Refresh und ein Sofort-Abruf nach dem Anlegen eines Zugangsdatums sind ebenfalls möglich.',
    'esxi_inv_p2' => 'Ist ein Abruf fehlgeschlagen, erscheint eine Fehlerkategorie (nicht erreichbar, Anmeldung, Berechtigungen, Ansible-Host, Auswertung). Bei falscher Anmeldung pausiert der automatische Abruf bis zur Änderung des Zugangsdatums (Schutz vor Kontosperren). Der Cache bleibt bei Fehlern erhalten; nichts wird gelöscht.',
    'esxi_inv_cadence' => 'Unter den Zeitstempeln jeder Inventarkarte steht, ob und in welchem Takt sich diese Werte erneuern. Nennt die Zeile stattdessen einen Grund (Automatik aus, kein Ansible-Zugang gewählt, Zugangsdatum pausiert), dann ist genau das der Grund, der den Abruf stoppt, und er ist zuerst zu beheben: die übrigen greifen erst danach wieder.',
    'esxi_inv_rights_heading' => 'Benötigte ESXi-Rechte',
    'esxi_inv_rights_read' => 'Inventar (read-only): Lesezugriff auf Datacenter, Datastores, Netzwerk/Portgruppen und Host-Objekte.',
    'esxi_inv_rights_deploy' => 'Deploy (Playbooks): VM anlegen, Datastore belegen, Netzwerk zuweisen, Power-Operationen sowie Disk-/NIC-Konfiguration.',
    'esxi_inv_p3' => 'Reicht ein Recht nicht, erscheint die Kategorie „unzureichende Berechtigungen"; dann die ESXi-Rolle des Kontos erweitern. Details stehen im Projektordner auf dem Server (nicht im Portal erreichbar): docs/operations/esxi-inventory.md.',
    'esxi_inv_deviation' => 'Werte, die nicht im aktuellen Inventar vorkommen, erscheinen als Abweichung (Abschnitt „Abweichungen" im Systemstatus, Badge in der Missionsliste, Hinweis beim Bereitstellen). Solange noch kein ESXi-Inventar vorliegt, gibt es nichts zu vergleichen; der Abschnitt meldet dann „Nicht geprüft" statt einer grünen Null. Abweichungen einer Vorlage sind als solche markiert, denn sie werden erst zum Problem, wenn daraus eine Mission entsteht. Geprüft werden Missionen, abweichende Werte einzelner VMs und die VLANs der Netzwerkkarten; der Badge leuchtet auch, wenn nur eine VM der Mission betroffen ist. Das blockiert nichts, sondern markiert einen Wert zum Prüfen. Wurde ein VLAN auf ESXi umbenannt, lassen sich mit der geführten Massen-Neuzuweisung alle Zuweisungen eines VLAN-Namens auf einen aktiven Eintrag umstellen; das betrifft nur Portal-Datensätze, nie ESXi. Das Formular erscheint nur, wenn es tatsächlich eine VLAN-Abweichung gibt.',
    'esxi_inv_refresh_pause' => 'Der Button „Alle aktualisieren" überspringt pausierte Zugangsdaten (Schutz vor Kontosperren) und weist im Hinweis darauf hin. Ein pausiertes Zugangsdatum lässt sich gezielt über den eigenen Aktualisieren-Button erneut versuchen oder durch Speichern der Zugangsdaten wieder aktivieren.',
    'esxi_inv_ampel_heading' => 'Ampel des Inventar-Abrufs',
    'esxi_inv_ampel_p1' => 'Die Ampel zeigt nur die Gesundheit des Abrufs. Rot: Anmeldung pausiert oder mindestens :streak Fehlversuche in Folge. Gelb: letzter Abruf fehlgeschlagen, noch nie erfolgreich oder der letzte Erfolg ist älter als das :factor-fache des Intervalls. Grün: letzter Abruf erfolgreich und aktuell. Bei Intervall 0 (Automatik aus) entfällt die Veraltet-Warnung; nur echte Fehler färben die Ampel. Host-Eigenschaften wie freie Lizenz oder HA-Cluster färben die Ampel nicht; sie erscheinen als eigene Badges (siehe „Hinweise zum Host"). Dieselbe Ampel steht auf der Seite Zugangsdaten und als Kachel „Hypervisor" auf dem Dashboard; sie können nicht auseinanderlaufen.',
    'esxi_inv_catalog_heading' => 'VLAN-Katalog: Präsenz und VLAN-ID',
    'esxi_inv_catalog_presence' => 'Die Spalte „Auf ESXi" zeigt, auf wie vielen erfolgreich abgerufenen Hosts eine Portgruppe existiert. Teilpräsenz (etwa auf 3 von 7 Hosts) ist gelb markiert und nennt die fehlenden Hosts: ein Deploy auf einen dieser Hosts würde die Portgruppe nicht finden.',
    'esxi_inv_catalog_vlanid' => 'Die Spalte „VLAN-ID" vergleicht die IDs gleichnamiger Portgruppen über die Hosts. Unterschiedliche IDs sind rot markiert, denn gleicher Name mit anderer ID bedeutet ein anderes Netz. Trunks/Bereiche werden nicht verglichen; ältere Abrufe ohne ID-Daten zeigen einen Platzhalter bis zum nächsten Abruf.',
    'esxi_inv_templates' => 'Der Abweichungsbericht zeigt auch Vorlagen (gekennzeichnet als „Vorlage"): ein veraltetes VLAN, das nur noch in einer Vorlage steckt, würde sonst unbemerkt in jede daraus erzeugte Mission wandern. Ein Klick auf einen VLAN-Abweichungswert befüllt die Massen-Neuzuweisung vor.',
    'esxi_test_heading' => 'Zugangsdaten testen',
    'esxi_test_p1' => 'Das Portal spricht ESXi nie direkt an. Die Aktion „Inventarabruf starten" auf der Seite Zugangsdaten reiht für ein ESXi-Konto denselben read-only Abruf ein, den auch das Speichern auslöst: über den Ansible-Host, also genau den Weg, den ein Deploy nimmt. Die Meldung bestätigt zunächst nur Warteschlange oder offenen Auftrag.',
    'esxi_test_p2' => 'Das Ergebnis steht danach dauerhaft als Ampel auf dieser Seite, nicht als einmalige Meldung. Ein Klick auf die Status-Marke unter Zugangsdaten springt zum genauen Eintrag, hebt ihn hervor und lässt ihn vollständig unter der festen Kopfzeile sichtbar. Eingereihte und laufende Aufträge sind dort ebenso direkt mit ihrem Jobprotokoll verlinkt wie der letzte beendete Abruf – auch nach einem Erfolg, damit sich Teilabfragen prüfen lassen. Nach Ablauf der Aufbewahrung erscheint bei einem alten Fehler ein Hinweis statt eines toten Links; ein neuer Abruf erzeugt ein neues Protokoll.',
    'esxi_test_ansible_heading' => 'Ansible-Zugang: was der Test prüft',
    'esxi_test_ansible_p1' => 'Ein Ansible-Zugang wird sofort und vollständig geprüft, denn dieser Weg läuft aus dem Portal heraus: SSH-Anmeldung, dann die Toolchain auf dem Host (ansible-playbook, python3, die Python-Module pyvmomi und requests und die Collection community.vmware), ein echter SFTP-Schreibtest in /tmp und, sofern eine API-Basis-URL gesetzt ist, ob der Host das Portal erreicht (health.php) und ob seine IP in den Machine-API IP-Freigaben steht. Fehlt die Freigabe, ist das Ergebnis eine Warnung, kein Fehlschlag: der Zugang funktioniert, aber der MAC-Upload eines Deploys würde abgelehnt. Schlägt etwas fehl, nennt die Meldung die betroffene Komponente statt nur eines Exit-Codes; die Rohausgabe steht hinter „Technische Details".',
    'esxi_test_ansible_p2' => 'Das Ergebnis bleibt sichtbar: als Status-Marke in der Spalte „Status" auf der Seite Zugangsdaten und als eigene Zeile im Abschnitt „Ansible-Host" des Systemstatus, jeweils mit dem Zeitpunkt des letzten manuellen Volltests. Anders als der ESXi-Abruf läuft dieser Test nur auf Klick, nicht automatisch; deshalb wechselt die Ampel auf „Test veraltet", sobald das Ergebnis zu alt ist. Das ist kein Fehlerzustand, sondern fehlender aktueller Nachweis. Der Volltest lässt sich direkt in der Statuszeile erneut starten; „Prüfprotokolle öffnen" führt zur bestehenden Auditspur der Zugangsdaten.',
    'esxi_test_ansible_p3' => 'Getrennt daneben steht der letzte Missionsauftrag, den ein Worker tatsächlich bearbeitet hat, mit Ausgang, Zeit, Mission und, sofern berechtigt, direktem Jobprotokoll. Ein Auftrag, der vor dem Start aus der Warteschlange abgebrochen wurde, erscheint dort nicht: er wurde nie ausgeführt. Diese Zeile ist kein Zugangstest und beeinflusst die Volltest-Ampel nicht. Sie zeigt nur, wie weit dieser eine Auftrag kam; ein Start- oder Shutdown-Auftrag prüft beispielsweise nicht zwingend den MAC-Rückkanal. Wird der Zugang bearbeitet, verwirft das Portal deshalb weiterhin das Volltestergebnis und die Marke steht auf „Nicht getestet". Nach jeder Änderung einmal neu testen.',
    'esxi_cap_heading' => 'Hinweise zum Host lesen',
    'esxi_cap_p1' => 'Nach einem erfolgreichen Abruf zeigt das Portal, was der Host ist (Produkt, Version, Lizenz, direkt oder über vCenter) und was er gerade tut. Diese Hinweise besagen nicht, dass etwas kaputt ist, sondern was der Host kann:',
    'esxi_cap_unknown' => 'Ist eine Angabe unbekannt, erscheint gar kein Hinweis. Sie wird nie als „ist in Ordnung" gelesen. Ein Auftrag wird nur abgelehnt, wenn die Angabe aus einem frischen erfolgreichen Abruf stammt; veraltete Angaben warnen nur und lassen den Auftrag laufen.',
    'esxi_inv_host_facts' => 'Unter „Inventardetails öffnen" nennt jede Host-Zeile zusätzlich die Kernanzahl. Weicht die Uhr des Hosts zum Zeitpunkt des Abrufs um mehr als :minutes Minuten von der Portal-Zeit ab, steht dort eine Warnung: eine stark verstellte ESXi-Uhr kann den Domänenbeitritt frisch erzeugter VMs brechen (Kerberos toleriert nur wenige Minuten). Behoben wird das per NTP auf dem ESXi-Host, nicht im Portal.',
    'esxi_cause_heading' => 'Ursachen eines fehlgeschlagenen Abrufs',
    'esxi_cause_p1' => 'Schlägt ein Abruf fehl, ordnet das Portal die Ursache einer festen Kategorie zu. Solange der Auftrag aufbewahrt wird, führt der Fehlerhinweis direkt in sein Jobprotokoll mit dem technischen Originaltext. Nach der Aufbewahrungsfrist wird der tote Link entfernt; dann einen neuen Abruf starten.',
    'esxi_cause_th_cause' => 'Kategorie',
    'esxi_cause_th_meaning' => 'Bedeutung',
    'esxi_cause_th_fix' => 'Abhilfe',
    'esxi_cause_host_placeholder' => 'dem Host',
    'esxi_cause_fix_dns' => 'Hostnamen im Zugangsdatum prüfen, dazu DNS und Suchdomäne des Portal-Containers.',
    'esxi_cause_fix_unreachable' => 'Netzwerk, Firewall und Port prüfen. Der Abruf wird beim nächsten Intervall automatisch wiederholt; der alte Bestand bleibt erhalten.',
    'esxi_cause_fix_certificate' => 'In den Zugangsdaten das CA-Bundle oder Serverzertifikat und den ESXi-Hostnamen prüfen, danach den strikten Verbindungstest erneut starten.',
    'esxi_cause_fix_tls' => 'TLS-Version, HTTPS-Port und Gegenstelle prüfen. Zertifikatsfehler erscheinen getrennt als certificate.',
    'esxi_cause_fix_auth' => 'Benutzername und Secret korrigieren. Der automatische Abruf pausiert bis zur Änderung, damit das ESXi-Konto nicht gesperrt wird.',
    'esxi_cause_fix_authz' => 'Die Rolle des ESXi-Kontos erweitern. Für das Inventar genügen Leserechte, für Bereitstellen und Autostart nicht.',
    'esxi_cause_fix_ansible_dns' => 'Ansible-Hostname sowie DNS und Suchdomäne des Portal-Containers prüfen. Der ESXi-Hostname ist davon nicht betroffen.',
    'esxi_cause_fix_ansible_unreachable' => 'Netzwerk, Firewall und SSH-Port zwischen Portal und Ansible-Host prüfen.',
    'esxi_cause_fix_ansible_auth' => 'Benutzername, Secret und SSH-Anmeldeverfahren des Ansible-Zugangs prüfen. Der ESXi-Zugang wird dadurch nicht pausiert.',
    'esxi_cause_fix_ansible_authz' => 'Rechte der Ansible-Sitzung und der betroffenen entfernten Aktion prüfen. Der ESXi-Zugang wird dadurch nicht pausiert.',
    'esxi_cause_fix_ansible_preflight' => 'Im Jobprotokoll die fehlgeschlagene Toolchain-Komponente nachsehen und den Ansible-Host vervollständigen.',
    'esxi_cause_fix_ansible_config' => 'Playbook, Modul, Collection, Python-Abhängigkeiten, Rechteerhöhung (become) und Ansible-Ausführungsumgebung auf dem Ansible-Host prüfen.',
    'esxi_cause_fix_ansible_sftp' => 'SFTP-Subsystem, Zielpfad, Schreibrechte, freien Speicher und Dateiübertragung auf dem Ansible-Host prüfen.',
    'esxi_cause_fix_ansible_timeout' => 'Jobprotokoll und Ansible-Host auf einen stillstehenden SSH- oder SFTP-Schritt prüfen; dies ist ein VirtuSphere-Zeitbudget, kein ESXi-Timeout.',
    'esxi_cause_fix_ansible_transport' => 'Jobprotokoll sowie SSH-Dienst und Transportweg zum Ansible-Host prüfen.',
    'esxi_cause_fix_http' => 'Nur lesbarer Legacy-Wert. Erscheint er an einem alten Datensatz, ordnet ein neuer Abruf die Ursache mit dem aktuellen Vokabular ein.',
    'esxi_cause_fix_ssh' => 'Kein neuer Abruf schreibt diesen Wert mehr; er stammt aus einem Abruf vor der Herkunftstrennung und benennt keinen Verursacher. Das Jobprotokoll des Abrufs nennt die tatsächliche Ursache; ein neuer Abruf ersetzt den Wert durch eine Kategorie, die den Verursacher benennt.',
    'esxi_cause_fix_worker' => 'Deploy-Worker, Datenbankverbindung und Jobprotokoll prüfen; die Kategorie behauptet keine Transportursache.',
    'esxi_cause_fix_parse' => 'Jobprotokoll auf fehlenden Marker, unerwartete Ausgabe oder einen verletzten Ergebnisvertrag prüfen.',
    'esxi_cause_fix_config' => 'Portal- und Auftragskonfiguration prüfen. Dieser Code gilt vor dem entfernten Lauf; Ansible-seitige Voraussetzungen haben eine eigene Kategorie.',
    'esxi_inv_zero_heading' => 'Grüner Abruf, trotzdem eine 0',
    'esxi_inv_zero_p1' => 'Ein Abruf besteht aus mehreren getrennten Abfragen: Datacenter, Datastores, Standard-Portgruppen, Distributed-Portgruppen und Host-Daten. Bleibt eine davon ohne Ergebnis, läuft der Abruf trotzdem sauber zu Ende; die Karte zeigt für diese Art eine 0 und die Ampel bleibt grün, weil sie nur beantwortet, ob der Abruf gelaufen ist. Eine 0 neben gefüllten Zahlen ist deshalb kein Widerspruch, sondern der Hinweis, genau eine Abfrage nachzusehen.',
    'esxi_inv_zero_p2' => 'Entscheidend ist, worauf das Zugangsdatum zeigt. Standard-Portgruppen und Host-Daten liest das Portal am ESXi-Host selbst; zeigt das Zugangsdatum auf ein vCenter, bleiben genau diese beiden leer, während Datacenter und Datastores ankommen. Distributed-Portgruppen gibt es umgekehrt nur unter vCenter: an einem einzelnen ESXi-Host ist ihre 0 der Normalfall. Für ein vollständiges Inventar ist ein Zugangsdatum auf den ESXi-Host der geprüfte Weg.',
    'esxi_inv_zero_p3' => 'Raten muss dafür niemand: jeder Abruf protokolliert selbst, welche seiner Abfragen geantwortet hat. Im Job-Log des Auftrags steht direkt unter den Zahlen die Zeile „Inventory queries". Entweder meldet sie, dass alle Abfragen geantwortet haben („all ... answered"), dann sind alle Zahlen belastbar und eine 0 ist eine echte 0. Oder sie nennt jede stumme Abfrage mit einem von zwei Wörtern: „rejected" heißt, die Abfrage wurde abgelehnt, oft bevor sie ESXi überhaupt erreicht hat, und die Meldung dahinter stammt wörtlich vom Modul; „skipped" heißt, das Playbook hatte nichts zu fragen, etwa Distributed-Portgruppen ohne bekanntes Datacenter. Scheitern mehrere Abfragen an derselben Ursache, werden sie gemeinsam vor einer Meldung genannt.',
    'esxi_inv_zero_p4' => 'Verloren geht dabei nichts: ein leeres Teilergebnis lässt den vorhandenen Stand dieser Art unangetastet, und der VLAN-Katalog zieht eine Portgruppe erst zurück, wenn ein Abruf sie nachweislich nicht mehr meldet. Fehlt die Zeile „Inventory queries" ganz, stammt der Abruf aus einem älteren Stand, der noch nichts über seine Vollständigkeit sagen konnte; dann hilft ein neuer Abruf.',
    'esxi_inv_zero_p5' => 'Direkt darunter steht die Zeile „Datastore health". Sie nennt, für wie viele Datastores der Abruf Erreichbarkeit und Wartungsmodus überhaupt mitgeliefert hat, und danach namentlich die, die im Wartungsmodus oder nicht erreichbar sind. Auch der gute Fall steht dort, aus demselben Grund wie bei den Abfragen: eine Flotte ohne Wartung und ein Feld, das der Abruf gar nicht mehr trifft, sähen sonst gleich aus. Ein Datastore im Wartungsmodus wird in den Auswahllisten gekennzeichnet, und sein freier Speicher gilt überall als unbekannt statt als verfügbar.',
];
